 background: submitting ? "#90caf9" : "#0066cc",
 color: "#fff",
 border: "none",
 borderRadius: 12,
 fontSize: 16,
 fontWeight: 600,
 cursor: submitting ? "not-allowed" : "pointer",
 opacity: submitting ? 0.7 : 1,
 }}
 >
 {submitting ? "Submitting..." : "Submit Report"}
 </button>
 </div>
 );
}
","import React, { useState, useEffect } from "react";

interface Props {
 navigate: (view: string, extras?: { type?: string; id?: string }) => void;
}

function dv(field: any): string {
 if (!field) return "";
 if (typeof field === "string") return field;
 if (typeof field === "object") return field.display_value || field.value || "";
 return String(field);
}

function getSysId(record: any): string {
 const id = record?.sys_id;
 if (!id) return "";
 if (typeof id === "string") return id;
 return id.value || id.display_value || "";
}

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 Accept: "application/json",
 "Content-Type": "application/json",
 };
 const token = (window as any).g_ck;
 if (token) headers["X-UserToken"] = token;
 return headers;
}

export default function MyBusScreen({ navigate }: Props) {
 const [buses, setBuses] = useState<any[]>([]);
 const [selectedBus, setSelectedBus] = useState<any>(null);
 const [stops, setStops] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [loadingStops, setLoadingStops] = useState(false);
 const [error, setError] = useState("");

 useEffect(() => {
 const fetchBuses = async () => {
 try {
 const res = await fetch(
 "/api/now/table/u_bus?sysparm_display_value=all&sysparm_limit=10",
 { headers: getHeaders() }
 );
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const data = await res.json();
 const busList = data.result || [];
 setBuses(busList);
 if (busList.length > 0) {
 selectBus(busList[0]);
 }
 } catch (e: any) {
 setError(e.message || "Failed to load buses.");
 } finally {
 setLoading(false);
 }
 };
 fetchBuses();
 }, []);

 const selectBus = async (bus: any) => {
 setSelectedBus(bus);
 setStops([]);

 // Get route sys_id from the bus's u_route field
 const routeRef = bus?.u_route;
 let routeSysId = "";
 if (routeRef) {
 if (typeof routeRef === "string") routeSysId = routeRef;
 else routeSysId = routeRef.value || "";
 }

 if (!routeSysId) return;

 setLoadingStops(true);
 try {
 const res = await fetch(
 `/api/now/table/u_bus_stop?sysparm_query=u_route_id=${routeSysId}^u_isactive=true&sysparm_display_value=all&sysparm_limit=20`,
 { headers: getHeaders() }
 );
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const data = await res.json();
 setStops(data.result || []);
 } catch (e: any) {
 // Silently handle stops fetch error
 } finally {
 setLoadingStops(false);
 }
 };

 if (loading) {
 return (
 <div style={{ padding: 16, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "60vh" }}>
 <div style={{ width: 40, height: 40, border: "4px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite" }} />
 <p style={{ marginTop: 16, color: "#666", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>Loading bus info...</p>
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 );
 }

 if (error) {
 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 <h1 style={{ margin: "0 0 16px", fontSize: 22, fontWeight: 700, color: "#1a1a1a" }}>My Bus</h1>
 <div style={{ background: "#fdecea", color: "#c62828", padding: 16, borderRadius: 8, fontSize: 14 }}>
 {error}
 </div>
 </div>
 );
 }

 const busNumber = selectedBus ? dv(selectedBus.u_bus_number) : "";
 const busStatus = selectedBus ? dv(selectedBus.u_bus_status) : "";
 const busRoute = selectedBus ? dv(selectedBus.u_route) : "";
 const busLat = selectedBus ? dv(selectedBus.u_current_latitude) : "";
 const busLon = selectedBus ? dv(selectedBus.u_current_longitude) : "";
 const lastUpdate = selectedBus ? dv(selectedBus.u_last_location_update) : "";

 const statusColor = busStatus.toLowerCase() === "active" || busStatus.toLowerCase() === "on time"
 ? { bg: "#e8f5e9", text: "#2e7d32" }
 : busStatus.toLowerCase() === "delayed"
 ? { bg: "#fff8e1", text: "#f57f17" }
 : { bg: "#f5f5f5", text: "#616161" };

 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 {/* Header */}
 <div style={{ marginBottom: 16 }}>
 <h1 style={{ margin: 0, fontSize: 22, fontWeight: 700, color: "#1a1a1a" }}>My Bus</h1>
 </div>

 {/* Bus selector (if multiple buses) */}
 {buses.length > 1 && (
 <div style={{ display: "flex", gap: 8, marginBottom: 16, overflowX: "auto" }}>
 {buses.map((b) => {
 const bId = getSysId(b);
 const isSelected = selectedBus && getSysId(selectedBus) === bId;
 return (
 <button
 key={bId}
 onClick={() => selectBus(b)}
 style={{
 padding: "8px 14px",
 borderRadius: 20,
 border: "none",
 fontSize: 13,
 fontWeight: 600,
 cursor: "pointer",
 whiteSpace: "nowrap",
 background: isSelected ? "#0066cc" : "#f0f0f0",
 color: isSelected ? "#fff" : "#555",
 }}
 >
 {dv(b.u_bus_number)}
 </button>
 );
 })}
 </div>
 )}

 {/* Empty state */}
 {buses.length === 0 && (
 <div style={{ textAlign: "center", padding: "40px 16px" }}>
 <div style={{ fontSize: 48, marginBottom: 12 }}>🚌</div>
 <p style={{ color: "#666", fontSize: 15, margin: 0 }}>No buses available at this time.</p>
 </div>
 )}

 {/* Bus info card */}
 {selectedBus && (
 <div style={{
 background: "linear-gradient(135deg, #e3f2fd 0%, #f5f5f5 100%)",
 borderRadius: 14,
 padding: 18,
 marginBottom: 20,
 border: "1px solid #bbdefb",
 }}>
 <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
 <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
 <div style={{
 width: 44,
 height: 44,
 background: "#0066cc",
 borderRadius: 12,
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 color: "#fff",
 fontWeight: 700,
 fontSize: 16,
 }}>
 {busNumber.replace(/[^\d]/g, "").slice(0, 3) || "?"}
 </div>
 <div>
 <div style={{ fontSize: 16, fontWeight: 700, color: "#1a1a1a" }}>Bus {busNumber}</div>
 <div style={{ fontSize: 12, color: "#666" }}>{busRoute}</div>
 </div>
 </div>
 <span style={{
 fontSize: 11,
 fontWeight: 600,
 padding: "4px 10px",
 borderRadius: 12,
 background: statusColor.bg,
 color: statusColor.text,
 }}>
 {busStatus || "Unknown"}
 </span>
 </div>

 <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
 <div style={{ textAlign: "center", background: "#fff", borderRadius: 10, padding: "10px 8px" }}>
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a" }}>{busLat ? `${parseFloat(busLat).toFixed(3)}°` : "—"}</div>
 <div style={{ fontSize: 10, color: "#888", marginTop: 2 }}>Latitude</div>
 </div>
 <div style={{ textAlign: "center", background: "#fff", borderRadius: 10, padding: "10px 8px" }}>
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a" }}>{busLon ? `${parseFloat(busLon).toFixed(3)}°` : "—"}</div>
 <div style={{ fontSize: 10, color: "#888", marginTop: 2 }}>Longitude</div>
 </div>
 <div style={{ textAlign: "center", background: "#fff", borderRadius: 10, padding: "10px 8px" }}>
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a" }}>{lastUpdate ? "✓" : "—"}</div>
 <div style={{ fontSize: 10, color: "#888", marginTop: 2 }}>Updated</div>
 </div>
 </div>

 {lastUpdate && (
 <div style={{ marginTop: 10, fontSize: 11, color: "#666", textAlign: "center" }}>
 Last updated: {lastUpdate}
 </div>
 )}
 </div>
 )}

 {/* Route Stops */}
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a", marginBottom: 12 }}>Route Stops</div>

 {loadingStops && (
 <div style={{ textAlign: "center", padding: 20 }}>
 <div style={{ width: 24, height: 24, border: "3px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite", margin: "0 auto" }} />
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 )}

 {!loadingStops && stops.length === 0 && selectedBus && (
 <div style={{ textAlign: "center", padding: "20px 16px", color: "#888", fontSize: 13 }}>
 No stops found for this bus route.
 </div>
 )}

 {!loadingStops && stops.length > 0 && (
 <div style={{ display: "flex", flexDirection: "column", gap: 0 }}>
 {stops.map((stop, i) => {
 const stopName = dv(stop.u_stop_name);
 const lat = dv(stop.u_latitude);
 const lon = dv(stop.u_longtitude); // Note: typo in schema

 return (
 <div key={getSysId(stop)} style={{ display: "flex", alignItems: "stretch", gap: 12 }}>
 {/* Timeline indicator */}
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: 20 }}>
 <div style={{
 width: 12,
 height: 12,
 borderRadius: "50%",
 background: i === 0 ? "#0066cc" : "#bbb",
 border: `2px solid ${i === 0 ? "#0066cc" : "#ddd"}`,
 flexShrink: 0,
 marginTop: 4,
 }} />
 {i < stops.length - 1 && (
 <div style={{ width: 2, flexGrow: 1, background: "#ddd", minHeight: 30 }} />
 )}
 </div>
 {/* Stop info */}
 <div style={{ paddingBottom: 16, flex: 1 }}>
 <div style={{ fontSize: 14, fontWeight: 600, color: "#1a1a1a" }}>{stopName}</div>
 {lat && lon && (
 <div style={{ fontSize: 11, color: "#888", marginTop: 2 }}>
 {parseFloat(lat).toFixed(4)}, {parseFloat(lon).toFixed(4)}
 </div>
 )}
 </div>
 </div>
 );
 })}
 </div>
 )}

 {/* Live location placeholder */}
 {selectedBus && busLat && busLon && (
 <>
 <div style={{ fontSize: 15, fontWeight: 700, color: "#1a1a1a", marginTop: 20, marginBottom: 12 }}>Live Location</div>
 <div style={{
 background: "#f9f9f9",
 borderRadius: 12,
 padding: 24,
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 justifyContent: "center",
 border: "1px dashed #ddd",
 }}>
 <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#999" strokeWidth="1.5" opacity={0.6}>
 <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7z" />
 <circle cx="12" cy="9" r="2.5" />
 </svg>
 <div style={{ marginTop: 8, fontSize: 13, color: "#666" }}>
 📍 {parseFloat(busLat).toFixed(5)}, {parseFloat(busLon).toFixed(5)}
 </div>
 <div style={{ marginTop: 4, fontSize: 11, color: "#999" }}>Map visualization coming soon</div>
 </div>
 </>
 )}
 </div>
 );
}
