","import React, { useState, useEffect } from "react";

interface Props {
 navigate: (view: string, extras?: { type?: string; id?: string }) => void;
}

function dv(field: any): string {
 if (!field) return "";
 if (typeof field === "string") return field;
 if (typeof field === "object") return field.display_value || field.value || "";
 return String(field);
}

function getSysId(record: any): string {
 const id = record?.sys_id;
 if (!id) return "";
 if (typeof id === "string") return id;
 return id.value || id.display_value || "";
}

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 Accept: "application/json",
 "Content-Type": "application/json",
 };
 const token = (window as any).g_ck;
 if (token) headers["X-UserToken"] = token;
 return headers;
}

function getStatusColor(state: string): { bg: string; text: string } {
 const s = state.toLowerCase();
 if (s === "open") return { bg: "#fff8e1", text: "#f57f17" };
 if (s === "in progress") return { bg: "#e3f2fd", text: "#1565c0" };
 if (s === "resolved" || s === "approved") return { bg: "#e8f5e9", text: "#2e7d32" };
 return { bg: "#f5f5f5", text: "#616161" };
}

export default function MyRequestsScreen({ navigate }: Props) {
 const [cases, setCases] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");
 const [activeFilter, setActiveFilter] = useState("All");

 useEffect(() => {
 const fetchCases = async () => {
 try {
 const res = await fetch(
 "/api/now/table/u_transportation_case?sysparm_display_value=all&sysparm_limit=30&sysparm_query=ORDERBYDESCsys_created_on",
 { headers: getHeaders() }
 );
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const data = await res.json();
 setCases(data.result || []);
 } catch (e: any) {
 setError(e.message || "Failed to load requests.");
 } finally {
 setLoading(false);
 }
 };
 fetchCases();
 }, []);

 const filters = ["All", "Open", "In Progress", "Resolved"];

 const filteredCases = cases.filter((c) => {
 if (activeFilter === "All") return true;
 const state = dv(c.u_state);
 return state.toLowerCase() === activeFilter.toLowerCase();
 });

 if (loading) {
 return (
 <div style={{ padding: 16, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "60vh" }}>
 <div style={{ width: 40, height: 40, border: "4px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite" }} />
 <p style={{ marginTop: 16, color: "#666", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>Loading requests...</p>
 <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
 </div>
 );
 }

 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 {/* Header */}
 <div style={{ marginBottom: 16 }}>
 <h1 style={{ margin: 0, fontSize: 22, fontWeight: 700, color: "#1a1a1a" }}>My Requests</h1>
 </div>

 {/* Filter chips */}
 <div style={{ display: "flex", gap: 8, marginBottom: 20, overflowX: "auto" }}>
 {filters.map((f) => (
 <button
 key={f}
 onClick={() => setActiveFilter(f)}
 style={{
 padding: "8px 16px",
 borderRadius: 20,
 border: "none",
 fontSize: 13,
 fontWeight: 600,
 cursor: "pointer",
 whiteSpace: "nowrap",
 background: activeFilter === f ? "#0066cc" : "#f0f0f0",
 color: activeFilter === f ? "#fff" : "#555",
 }}
 >
 {f}
 </button>
 ))}
 </div>

 {error && (
 <div style={{ background: "#fdecea", color: "#c62828", padding: 12, borderRadius: 8, marginBottom: 16, fontSize: 13 }}>
 {error}
 </div>
 )}

 {/* Empty state */}
 {!error && filteredCases.length === 0 && (
 <div style={{ textAlign: "center", padding: "40px 16px" }}>
 <div style={{ fontSize: 48, marginBottom: 12 }}>📋</div>
 <p style={{ color: "#666", fontSize: 15, margin: 0 }}>
 {activeFilter === "All" ? "No requests yet. Report an issue to get started!" : `No ${activeFilter.toLowerCase()} requests.`}
 </p>
 </div>
 )}

 {/* Request cards */}
 <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
 {filteredCases.map((c) => {
 const state = dv(c.u_state);
 const colors = getStatusColor(state);
 const caseNumber = dv(c.u_number);
 const shortDesc = dv(c.u_short_description);
 const issueType = dv(c.u_issue_type);
 const createdOn = dv(c.sys_created_on);

 return (
 <div
 key={getSysId(c)}
 onClick={() => navigate("request-detail", { id: getSysId(c) })}
 style={{
 background: "#fff",
 borderRadius: 12,
 padding: 16,
 boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
 border: "1px solid #f0f0f0",
 cursor: "pointer",
 transition: "transform 0.1s",
 }}
 >
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
 <span style={{ fontSize: 12, fontWeight: 700, color: "#0066cc" }}>{caseNumber}</span>
 <span style={{ fontSize: 11, fontWeight: 600, padding: "3px 10px", borderRadius: 12, background: colors.bg, color: colors.text }}>
 {state}
 </span>
 </div>
 <div style={{ fontSize: 15, fontWeight: 600, color: "#1a1a1a", marginBottom: 6 }}>{shortDesc}</div>
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
 <span style={{ fontSize: 12, color: "#888", background: "#f5f5f5", padding: "2px 8px", borderRadius: 8 }}>{issueType}</span>
 <span style={{ fontSize: 11, color: "#999" }}>{createdOn}</span>
 </div>
 </div>
 );
 })}
 </div>
 </div>
 );
}
