export default function RequestDetailScreen({ navigate, requestId }: Props) {
 const [caseData, setCaseData] = useState<any>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState("");

 useEffect(() => {
 if (!requestId) {
 setError("No request ID provided.");
 setLoading(false);
 return;
 }

 const fetchCase = async () => {
 try {
 const res = await fetch(
 `/api/now/table/u_transportation_case/${requestId}?sysparm_display_value=all`,
 { headers: getHeaders() }
 );
 if (!res.ok) throw new Error(`HTTP ${res.status}`);
 const data = await res.json();
 setCaseData(data.result);
 } catch (e: any) {
 setError(e.message || "Failed to load request details.");
 } finally {
 setLoading(false);
 }
 };
 fetchCase();
 }, [requestId]);

 if (loading) {
 return (
 <div style={{ padding: 16, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", minHeight: "60vh" }}>
 <div style={{ width: 40, height: 40, border: "4px solid #e0e0e0", borderTopColor: "#0066cc", borderRadius: "50%", animation: "spin 1s linear infinite" }} />
 <p style={{ marginTop: 16, color: "#666", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>Loading details...</p>
