 <path d="M19 12H5M12 19l-7-7 7-7" />
 </svg>
 <span style={{ marginLeft: 8, fontSize: 14, color: "#333" }}>Back</span>
 </button>
 <div style={{ background: "#fdecea", color: "#c62828", padding: 16, borderRadius: 8, fontSize: 14 }}>
 {error || "Request not found."}
 </div>
 </div>
 );
 }

 const caseNumber = dv(caseData.u_number);
 const issueType = dv(caseData.u_issue_type);
 const state = dv(caseData.u_state);
 const severity = dv(caseData.u_severity);
 const priority = dv(caseData.u_priority);
 const shortDesc = dv(caseData.u_short_description);
 const description = dv(caseData.u_description);
 const solutionResponse = dv(caseData.u_solution_response);
 const resolutionNotes = dv(caseData.u_resolution_notes);
 const currentBus = dv(caseData.u_current_bus);
 const currentRoute = dv(caseData.u_current_route);
 const currentStop = dv(caseData.u_current_bus_stop);
 const requestedRoute = dv(caseData.u_requested_route);
 const requestedStop = dv(caseData.u_requested_bus_stop);
 const createdOn = dv(caseData.sys_created_on);
 const stateColors = getStatusColor(state);
 const sevColors = getSeverityColor(severity);
 const isRouteChange = issueType.toLowerCase().includes("route change");

 return (
 <div style={{ padding: 16, fontFamily: "system-ui, sans-serif" }}>
 {/* Header */}
 <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 20 }}>
 <button
 onClick={() => navigate("requests")}
 style={{ background: "none", border: "none", padding: 4, cursor: "pointer", display: "flex", alignItems: "center" }}
 >
