 <label className="ms-label">Item Description</label>
 <input className="ms-input" placeholder="What did you lose?" />
 </div>
 <div className="ms-form-group">
 <label className="ms-label">Bus Route</label>
 <select className="ms-select">
 <option value="">Select route...</option>
 <option value="42">Route 42 — Campus Express</option>
 <option value="15">Route 15 — North Loop</option>
 <option value="7">Route 7 — Downtown Shuttle</option>
 </select>
 </div>
 <div className="ms-form-group">
 <label className="ms-label">Approximate Date & Time</label>
 <input className="ms-input" type="datetime-local" />
 </div>
 <div className="ms-form-group">
 <label className="ms-label">Additional Details</label>
 <textarea className="ms-textarea" rows={3} placeholder="Color, brand, where you were sitting..." />
