 {/* Location Tracking Card */}
 <div style={{ padding: "0 16px 16px" }}>
 <div style={{
 backgroundColor: "#ffffff",
 borderRadius: "16px",
 padding: "20px",
 boxShadow: tracking ? "0 0 0 2px #28a745, 0 4px 20px rgba(40,167,69,0.15)" : "0 2px 12px rgba(0,0,0,0.08)",
