 </div>
 )}

 {/* Map Area & Coordinates */}
 {tracking && position && (
 <div style={{
 backgroundColor: "#1e3a5f",
 borderRadius: "12px",
 padding: "16px",
 position: "relative",
 overflow: "hidden",
 }}>
 {/* Fake map grid lines */}
