 navigate: (view: string) => void;
}

const navItems = [
 { id: "home", label: "Dashboard", emoji: "🏠" },
 { id: "tracking", label: "Tracking", emoji: "📍" },
 { id: "alerts", label: "Alerts", emoji: "🔔" },
];

export default function DriverNav({ currentView, navigate }: Props) {
 return (
 <nav className="ms-bottom-nav">
 {navItems.map((item) => (
 <button
 key={item.id}
 className={`ms-nav-item ${currentView === item.id ? "ms-nav-active" : ""}`}
 onClick={() => navigate(item.id)}
 >
 <span style={{ fontSize: "1.25rem" }}>{item.emoji}</span>
 <span className="ms-nav-label">{item.label}</span>
 </button>
 ))}
 </nav>
 );
}
","import React, { useState, useEffect } from "react";

interface CaseRecord {
 sys_id: string;
 u_number: { display_value: string };
 u_case_number: { display_value: string };
 u_issue_type: { display_value: string };
 u_state: { display_value: string };
 u_priority: { display_value: string };
 u_short_description: { display_value: string };
 u_description: { display_value: string };
 u_solution_response: { display_value: string };
 u_resolution_notes: { display_value: string };
 u_current_bus: { display_value: string };
 u_current_route: { display_value: string };
 u_current_bus_stop: { display_value: string };
 sys_created_on: { display_value: string };
}

const API_BASE = "/api/now/table";

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 "Content-Type": "application/json",
 Accept: "application/json",
 };
 if ((window as any).g_ck) {
 headers["X-UserToken"] = (window as any).g_ck;
 }
 return headers;
}

const issueTypes = ["All", "Bus Delay", "Bus Not Arrived", "Overcrowded", "Route Change"];
const stateFilters = ["All States", "Open", "In Progress", "Resolved", "Approved"];

function getIssueIcon(issueType: string): string {
 const t = issueType?.toLowerCase() || "";
 if (t.includes("delay")) return "⏱️";
 if (t.includes("not arrived")) return "🚫";
 if (t.includes("overcrowded")) return "👥";
 if (t.includes("route")) return "🔄";
 return "📋";
}

function getIssueBorderColor(issueType: string): string {
 const t = issueType?.toLowerCase() || "";
 if (t.includes("delay")) return "#f59e0b";
 if (t.includes("not arrived")) return "#e63946";
 if (t.includes("overcrowded")) return "#e63946";
 if (t.includes("route")) return "#0080a3";
 return "#6c757d";
}

function getStateBadgeStyle(state: string): React.CSSProperties {
 const s = state?.toLowerCase() || "";
 if (s.includes("open")) return { backgroundColor: "#fff3cd", color: "#856404" };
 if (s.includes("progress")) return { backgroundColor: "#cce5ff", color: "#004085" };
 if (s.includes("resolved")) return { backgroundColor: "#d4edda", color: "#155724" };
 if (s.includes("approved")) return { backgroundColor: "#d4edda", color: "#155724" };
 return { backgroundColor: "#f0f2f5", color: "#6c757d" };
}

export default function AdminHome() {
 const [cases, setCases] = useState<CaseRecord[]>([]);
 const [loading, setLoading] = useState(true);
 const [selectedIssueType, setSelectedIssueType] = useState("All");
 const [selectedState, setSelectedState] = useState("All States");
 const [selectedCase, setSelectedCase] = useState<CaseRecord | null>(null);
 const [actionLoading, setActionLoading] = useState(false);

 const fetchCases = async () => {
 try {
 const res = await fetch(
 `${API_BASE}/u_transportation_case?sysparm_display_value=all&sysparm_limit=50&sysparm_query=ORDERBYDESCsys_created_on`,
 { headers: getHeaders() }
 );
 const data = await res.json();
 setCases(data.result || []);
 } catch (e) {
 console.error("Failed to fetch cases:", e);
 } finally {
 setLoading(false);
 }
 };

 useEffect(() => { fetchCases(); }, []);

 const filteredCases = cases.filter((c) => {
 const typeMatch = selectedIssueType === "All" || (c.u_issue_type?.display_value || "").toLowerCase().includes(selectedIssueType.toLowerCase());
 const stateMatch = selectedState === "All States" || (c.u_state?.display_value || "").toLowerCase().includes(selectedState.toLowerCase());
 return typeMatch && stateMatch;
 });

 const openCount = cases.filter((c) => (c.u_state?.display_value || "").toLowerCase().includes("open")).length;
 const resolvedCount = cases.filter((c) => {
 const s = (c.u_state?.display_value || "").toLowerCase();
 return s.includes("resolved") || s.includes("approved");
 }).length;

 const handleAction = async (caseRecord: CaseRecord, newState: string) => {
 setActionLoading(true);
 try {
 await fetch(`${API_BASE}/u_transportation_case/${caseRecord.sys_id}`, {
 method: "PATCH",
 headers: getHeaders(),
 body: JSON.stringify({ u_state: newState }),
 });
 await fetchCases();
 setSelectedCase(null);
 } catch (e) {
 console.error("Failed to update case:", e);
 } finally {
 setActionLoading(false);
 }
 };

 const screenStyle: React.CSSProperties = {
 minHeight: "100vh",
 backgroundColor: "#f4f6f9",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 paddingBottom: "80px",
 };

 if (loading) {
 return (
 <div style={screenStyle}>
 <div style={{ padding: "20px 16px", display: "flex", alignItems: "center", gap: "12px", backgroundColor: "#fff", borderBottom: "1px solid #e8ecf0" }}>
